const sessionId = data?.sessionId || 'default';
const memoryWindow = parseInt(node.properties.memoryWindow?.value || 10);

helpers.log(`[Session Memory] Using session: ${sessionId}`);

if (!execution['__sessionMemory']) {
  execution['__sessionMemory'] = {};
}

if (!execution['__sessionMemory'][sessionId]) {
  execution['__sessionMemory'][sessionId] = [];
  helpers.log('Initialized new session memory');
}

const sessionMessages = execution['__sessionMemory'][sessionId];
const recentMessages = sessionMessages.slice(-memoryWindow * 2);

helpers.log(`Loaded ${recentMessages.length} messages from session`);

return {
  messages: recentMessages,
  chatId: data?.chatId,
  sessionId,
  memoryWindow,
  type: 'session'
};
